const crypto = require('crypto');

const secret = $env.LINE_CHANNEL_SECRET || '';
const token = $env.LINE_CHANNEL_ACCESS_TOKEN || '';
const coreUrl = ($env.SNOW_COUNTRY_N8N_CORE_URL || '').replace(/\/$/, '');

const rawBody = $json.body ?? $json;
const signature = $headers['x-line-signature'] || $headers['X-Line-Signature'] || '';

function verify(sig, body, sec) {
  if (!sec) return true;
  const hmac = crypto.createHmac('sha256', sec).update(JSON.stringify(body)).digest('base64');
  return hmac === sig;
}

if (!verify(signature, rawBody, secret)) {
  return [{ json: { statusCode: 401, body: 'invalid signature' } }];
}

const events = rawBody.events || [];
const outputs = [];

for (const event of events) {
  if (event.type !== 'message' || event.message?.type !== 'text') continue;
  const userId = event.source?.userId;
  const text = event.message.text;
  const replyToken = event.replyToken;

  const coreRes = await fetch(coreUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ channel: 'line', userId, message: text }),
  });
  const core = await coreRes.json();
  const replyText = core.replyText || '系統繁忙，請稍後再試。';

  if (token && replyToken) {
    await fetch('https://api.line.me/v2/bot/message/reply', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + token,
      },
      body: JSON.stringify({ replyToken, messages: [{ type: 'text', text: replyText }] }),
    });
  }
  outputs.push({ json: { userId, replyText } });
}

if (!outputs.length) outputs.push({ json: { ok: true, note: 'no text events' } });
return outputs;
